// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        // Ensure token is not zero address to avoid trivial failures
        vm.assume(token != address(0));

        // First call to addReward should succeed (non-revert) if token not yet added
        // We'll capture its revert status
        bool firstReverted;
        try c.addReward(token) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Second call to addReward with same token
        bool secondReverted;
        try c.addReward(token) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: The second call must revert if the first succeeded (reference behavior)
        // For the mutant, the second call will succeed, so this rule will fail
        assertTrue(firstReverted || secondReverted);
    }
}

